Section EQ.
  Context {HCEIL : HeapCeil}.

Definition AEQ_STACK : Z := 96 + AGC_STACK.     (* [comment removed for export] *)

Definition eq_post_v (v : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P Q lo : Z) (bs cs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (if v then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ bytes_at bsegs m' P bs /\ bytes_at bsegs m' Q cs
    /\ ACONST m' /\ accessible m' P (Z.of_nat (length bs)) /\ accessible m' Q (Z.of_nat (length cs)).

Definition equals_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P Q lo : Z) (bs cs : list byte) (m : mem) : machine_state -> Prop :=
  eq_post_v (ft_ieqb (zbytes bs) (zbytes cs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P Q lo bs cs m.

Definition equals_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P Q lo : Z) (bs cs : list byte),
  bytes_at bsegs m P bs -> bytes_at bsegs m Q cs ->
  P + Z.of_nat (length bs) < 2^64 -> Q + Z.of_nat (length cs) < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AEQ_STACK <= bv_unsigned sp -> aceil <= lo ->      (* [comment removed for export] *)
  (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo) ->
  (bv_unsigned sp <= Q \/ Q + Z.of_nat (length cs) <= lo) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m P (Z.of_nat (length bs)) -> accessible m Q (Z.of_nat (length cs)) ->
  (* [comment removed for export] *)
  (0 < Z.of_nat (length bs) -> 0 < P) -> (0 < Z.of_nat (length cs) -> 0 < Q) ->
  evt bsegs (equals_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P Q lo bs cs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz (Z.of_nat (length bs))) (wz Q) (wz (Z.of_nat (length cs))) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELD_TABLE_EQUALS) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Definition eq_side (m : mem) (P n Q k : Z) : Prop := ACONST m /\ accessible m P n /\ accessible m Q k.
Lemma eq_side_now : forall m m1 P n Q k lo hi,
  eq_side m P n Q k -> munch [(lo, hi)]%Z m m1 -> wmono bsegs m m1 -> aceil <= lo -> eq_side m1 P n Q k.
Proof.
  intros m m1 P n Q k lo hi (AC & AW & AV) MU WM CEIL.
  assert (FW : Forall awin [(lo, hi)]%Z) by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_nil]).
  split; [eapply aconst_transport_awin; fast_eassumption|]. split; eapply acc_transport_awin; fast_eassumption.
Qed.

(* [comment removed for export] *)
Definition eq_ctx (m m1 : mem) (sp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v rav : word) (P Q lo : Z) (bs cs : list byte) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -96) [C8 s10v; C8 s9v; C8 s8v; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ bytes_at bsegs m1 P bs /\ bytes_at bsegs m1 Q cs
  /\ stk bsegs m1 lo (bv_unsigned sp + -96)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ eq_side m P (Z.of_nat (length bs)) Q (Z.of_nat (length cs)).

Definition eq_pure (sp : word) (P Q lo : Z) (bs cs : list byte) : Prop :=
  P + Z.of_nat (length bs) < 2^64 /\ Q + Z.of_nat (length cs) < 2^64 /\ lo + AEQ_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo)
  /\ (bv_unsigned sp <= Q \/ Q + Z.of_nat (length cs) <= lo)
  /\ (0 < Z.of_nat (length bs) -> 0 < P) /\ (0 < Z.of_nat (length cs) -> 0 < Q).

End EQ.

Ltac eq_open CTX PURE :=
  destruct CTX as (FR & WA & WB & ST & MU & WM & MI & SD);
  destruct PURE as (WAE & WBE & LO & CEIL & SEPP & SEPQ & PNZ & QNZ);
  pose proof (bytes_at_bound _ _ _ _ WA) as WAB; pose proof (bytes_at_bound _ _ _ _ WB) as WBB;
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPP; hydeL SEPQ;
  unfold AEQ_STACK, AGC_STACK in *.

