  lazymatch goal with
  | FR' : rw_cells _ ?mx (bv_unsigned ?sp + -96) [C8 ?x10; C8 ?x9; C8 ?x8; C8 ?x7; C8 ?x6; C8 ?x5; C8 ?x4; C8 ?x3; C8 ?x2; C8 ?x1; C8 ?x0; C8 ?xra],
    SD' : eq_side ?m0 ?P _ ?Q _ |- evt _ (eq_post_v _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?lo ?bs ?cs _) (MS _ _ _ _ _ ?mx _) =>
      assert (CTX2 : eq_ctx m0 mx sp x0 x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 xra P Q lo bs cs)
        by (unfold eq_ctx; repeat (split; [fast_eassumption|]); fast_eassumption)
  end.

